// Keep browser geometry independent of Wrangler's injected function-name helpers.
import { writeFileSync } from "node:fs";
import { calendarGeometry } from "../src/planner/model.mjs";
writeFileSync(
  new URL("../src/planner/geometry-source.mjs", import.meta.url),
  "// Generated by scripts/build-planner-source.mjs; verified by planner.test.mjs.\nexport const GEOMETRY_SOURCE=" +
    JSON.stringify(calendarGeometry.toString().replaceAll("\r\n", "\n")) +
    ";\n",
);
